CREATE TABLE ibexa_content_type_field_definition_ml (content_type_field_definition_id INTEGER NOT NULL, status INTEGER NOT NULL, language_id BIGINT NOT NULL, name VARCHAR(255) NOT NULL, description CLOB DEFAULT NULL, data_text CLOB DEFAULT NULL, data_json CLOB DEFAULT NULL, PRIMARY KEY(content_type_field_definition_id, status, language_id), CONSTRAINT ibexa_content_type_field_definition_ml_lang_fk FOREIGN KEY (language_id) REFERENCES ibexa_content_language (id) ON DELETE CASCADE NOT DEFERRABLE INITIALLY IMMEDIATE);
